import bpy, mathutils
from math import pi

def move_group(prefix, dx, dy, dyaw=0.0, pivot=None):
    if pivot is None:
        for o in bpy.data.objects:
            if o.name.startswith(prefix):
                o.matrix_world = mathutils.Matrix.Translation((dx,dy,0)) @ o.matrix_world
    else:
        R = mathutils.Matrix.Rotation(dyaw, 4, 'Z')
        px, py = pivot
        T1 = mathutils.Matrix.Translation((px, py, 0))
        T2 = mathutils.Matrix.Translation((-px, -py, 0))
        for o in bpy.data.objects:
            if o.name.startswith(prefix):
                o.matrix_world = T1 @ R @ T2 @ o.matrix_world

# verify chair rotation applied, then move left by 0.5 -> final center x = 2.45
